(* [comment removed for export] *)
Definition rta_tail_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lo R CH FAB nf n mfa au mu : Z) (ws : list word) (fl : list Z) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp - 208, bv_unsigned sp); (R, R + 8); (R + 16, R + 24); (R + 80, R + 88); (FAB + 4 * nf, FAB + 4 * (nf + n))]%Z m m'
    /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' R [C8 (wz 0); C4 (wz 0); C4 (wz 0); C8 (wz (nf + n)); C8 (wz mfa); C8 (wz au); C8 (wz 0); C8 (wz mu); C8 (wz 0)]
    /\ stk bsegs m' (R + 69) (R + 128)
    /\ u32arr bsegs m' FAB (wlist (rev fl) ++ ws) /\ stk bsegs m' (FAB + 4 * (nf + n)) (FAB + mfa)
    /\ u32arr bsegs m' CH ws.

Section Tail.
  Variables (ra sp gp tp : word) (rax t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 mm : word) (s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (lo sb ARI c CH FAB nf n mfa au mu : Z) (ws : list word) (fl : list Z) (j16 : list byte).
  Let R := ARI + REGIONINFO_SIZE * c.
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis ST : stk bsegs m lo (bv_unsigned sp + -128).
  Hypothesis LO : aceil <= lo.  Hypothesis HI : lo + 208 <= bv_unsigned sp.
  Hypothesis CR : 1 <= c < kNumClasses. Hypothesis NR : 1 <= n. Hypothesis NFR : 0 <= nf /\ 4 * (nf + n) <= mfa /\ mfa <= kFreeArraySize.
  Hypothesis ARIR : AHI_LO <= ARI /\ ARI + 4096 <= aceil /\ ARI mod 4096 = 0.
  Hypothesis CHR : akobj CH (4 * n) /\ CH + 4 * n <= aceil /\ CH mod 4 = 0.
  Hypothesis FABR : AHI_LO <= FAB /\ FAB + mfa <= aceil /\ FAB mod 4096 = 0.
  Hypothesis SEP : hidden ((CH + 4 * n <= FAB + 4 * nf \/ FAB + 4 * (nf + n) <= CH) /\ (CH + 4 * n <= R \/ R + 128 <= CH) /\ (R + 128 <= FAB \/ FAB + mfa <= R)).
  Hypothesis IRI : rw_cells bsegs m (AINST + 48) [C8 (wz ARI)].
  Hypothesis ISB : rw_cells bsegs m (AINST + 32) [C8 (wz sb); C4 (wz 0xffffffff); C4 (wz 0)].   (* [comment removed for export] *)
  Hypothesis GOT : rw_cells bsegs m AGOT_LO (map (fun v => C8 (wz v)) AGOT_VALS).
  Hypothesis PSC : rw_cells bsegs m APAGESZ [C8 (wz 4096)].
  Hypothesis FR : rw_cells bsegs m (bv_unsigned sp + -128)
                    [CB 16 j16; C8 (wz (R + 8)); C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].
  Hypothesis RI : rw_cells bsegs m R (rinfo_cells nf mfa au mu).
  Hypothesis RST : stk bsegs m (R + 69) (R + 128).
  Hypothesis SRC : u32arr bsegs m CH ws. Hypothesis WSL : length ws = Z.to_nat n.
  Hypothesis FARR : u32arr bsegs m FAB (wlist (rev fl)). Hypothesis FLL : length fl = Z.to_nat nf.
  Hypothesis FAJ : stk bsegs m (FAB + 4 * nf) (FAB + mfa).

  Let CHE : 4096 <= CH /\ CH + 4 * n <= aceil. Proof. exact (akobj_env _ _ (proj1 CHR) ltac:(lia)). Qed.
Scheme kc__6 := Elimination for OSSVerify.Proofs.boost_beast.http_request.lib.Bo.AllocWalkKit.hidden Sort Prop.   (* [comment removed for export] *)
  Theorem rta_tail :
